"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

P1 v0.4 pilot on dev: combine ours (L1) and L3 by averaging their scores (docs/iterations.md, 2026-11-19; the author
approved). Exploratory, dev only, no API. A combination entering the main comparison would need
a logged amendment before the freeze.

Design, fixed in the log before running:
- per decision point and per question (S, R): z = w * logit(p_L1) + (1 - w) * logit(p_L3), with probabilities clipped
  to [1e-7, 1 - 1e-7]; combined score = sigmoid(z). Primary: w = 0.5 (equal weights, no tuned knob). Exploratory:
  w = 0.25 and 0.75, and the plain probability average.
- thresholds by the plan's operating-point rule on dev (p1v4_score.operating_point, default grid), as for every system;
- reported: five-part mean, parts, floors, audio-decisive part; R-hear point accuracy by version; mid-confidence label
  following (trust curves: real vs false labels at 0.5-0.9); differences to B2-strong and to ours with the plan's
  interval; five-part mean by background-noise recording (ours, combination, B2-strong); the injection pilot (false
  phone labels at all eligible points) with each combination at its own dev thresholds.
Output: results/main_v04/combo_pilot_dev.json.
usage (repo root): .venv-gpu/Scripts/python.exe -X utf8 scripts/p1v4_combo_pilot.py
"""
import json
import math
import os
import sys
from collections import defaultdict

import numpy as np

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import p1v4_context as C  # noqa: E402
import p1v4_data as D  # noqa: E402
import p1v4_score as S  # noqa: E402
import p1v4_trust_curves as TC  # noqa: E402

R = "data/p1v4/runs"
EPS = 1e-7
VARIANTS = {"logit_w0.5": ("logit", 0.5), "logit_w0.25": ("logit", 0.25), "logit_w0.75": ("logit", 0.75),
            "prob_w0.5": ("prob", 0.5)}
PRIMARY = "logit_w0.5"


def keyed(d):
    return {(k.split("|")[0], k.split("|")[1], int(k.split("|")[2])): v for k, v in d.items()}


def logit(p):
    p = min(max(p, EPS), 1 - EPS)
    return math.log(p / (1 - p))


def combine(a, b, mode, w):
    out, mismatch = {}, 0
    for k in set(a) | set(b):
        x, y, d = a.get(k, {}), b.get(k, {}), {}
        for q in ("S", "R"):
            pa, pb = x.get(q), y.get(q)
            if pa is None and pb is None:
                continue
            if pa is None or pb is None:
                mismatch += 1
                d[q] = pb if pa is None else pa
            elif mode == "logit":
                d[q] = 1.0 / (1.0 + math.exp(-(w * logit(pa) + (1 - w) * logit(pb))))
            else:
                d[q] = w * pa + (1 - w) * pb
        out[k] = d
    return out, mismatch


def r_hear_versions(rows, dec):
    acc = defaultdict(list)
    ex = S.excluded_units()
    for r in rows:
        if r["part"] == "r_hear" and r["unit"] not in ex:
            for p in r["points"]:
                acc[r["version"]].append(dec.get((r["unit"], r["version"], p["k"]), {}).get("R") == p["gold"]["R"])
    return {v: float(np.mean(x)) for v, x in sorted(acc.items())}


def mid_follow(pts, dec):
    out = {}
    for real in (True, False):
        c = TC.curve(pts, dec, "not", real)
        n = sum(c[b]["n"] for b in ("0.5-0.7", "0.7-0.9"))
        k = sum(round(c[b]["n"] * c[b]["follow"]) for b in ("0.5-0.7", "0.7-0.9") if c[b]["follow"] is not None)
        out["real" if real else "false"] = [k, n]
    return out


def by_noise(T):
    noises = sorted({u["noise"] for u in T.values() if not str(u["noise"]).startswith("none:")})
    return {n: S.metrics({k: u for k, u in T.items() if u["noise"] == n})["primary"] for n in noises}


def summary(rows, groups, pts, dec):
    T = S.unit_table(rows, dec, groups)
    m = S.metrics(T)
    return T, {"primary": m["primary"], "parts": m["parts"], "floors": m["floors"], "audio": m["audio"],
               "r_hear_versions": r_hear_versions(rows, dec), "mid_confidence_follow": mid_follow(pts, dec)}


def main():
    rep = json.load(open("results/main_v04/dev_report.json"))["systems"]
    rows = D.load_rows("dev")
    groups = S.load_groups("dev")
    pts = TC.r_hear_points(rows, C.Context("dev"))
    l1 = keyed(json.load(open(f"{R}/l1/scores_dev.json")))
    l3 = keyed(json.load(open(f"{R}/l3/scores_dev.json")))
    i1 = keyed(json.load(open(f"{R}/inject_pilot/scores_L1.json")))
    i3 = keyed(json.load(open(f"{R}/inject_pilot/scores_L3.json")))
    op = rep["B2-strong"]["operating_point"]
    b2 = S.decide(keyed(json.load(open(f"{R}/api/b2strong/scores_dev_{op['setting']}.json"))), op["th_s"], op["th_r"])
    T_b2, ref_b2 = summary(rows, groups, pts, b2)
    op = rep["L1"]["operating_point"]
    d_l1 = S.decide(l1, op["th_s"], op["th_r"])
    T_l1, ref_l1 = summary(rows, groups, pts, d_l1)
    inj_l1 = S.metrics(S.unit_table(rows, S.decide(i1, op["th_s"], op["th_r"]), groups))["primary"]
    res = {"design": __doc__.split("Design, fixed in the log before running:")[1].split("Output:")[0].strip(),
           "reference": {"ours": dict(ref_l1, injected_primary=inj_l1, noise=by_noise(T_l1)),
                         "B2-strong": dict(ref_b2, noise=by_noise(T_b2))},
           "variants": {}}
    for name, (mode, w) in VARIANTS.items():
        sc, mismatch = combine(l1, l3, mode, w)
        opc = S.operating_point(rows, sc)
        dec = S.decide(sc, opc["th_s"], opc["th_r"])
        T, s = summary(rows, groups, pts, dec)
        isc, _ = combine(i1, i3, mode, w)
        idec = S.decide(isc, opc["th_s"], opc["th_r"])
        s.update(th_s=opc["th_s"], th_r=opc["th_r"], floors_met=opc["floors_met"], mismatch=mismatch,
                 injected_primary=S.metrics(S.unit_table(rows, idec, groups))["primary"],
                 injected_r_hear_versions=r_hear_versions(rows, idec), noise=by_noise(T))
        if name == PRIMARY:
            s["vs_B2_strong"] = {w_: S.interval(T, T_b2, w_) for w_ in ("primary", "audio", "part:r_hear")}
            s["vs_ours"] = {w_: S.interval(T, T_l1, w_) for w_ in ("primary", "audio", "part:r_hear")}
            noises = sorted(s["noise"])
            s["vs_B2_strong_without_noise"] = {}
            for n in noises:
                keep = [u for u in T if T[u]["noise"] != n]
                s["vs_B2_strong_without_noise"][n] = S.interval({u: T[u] for u in keep}, {u: T_b2[u] for u in keep},
                                                                "primary")
        res["variants"][name] = s
    json.dump(res, open("results/main_v04/combo_pilot_dev.json", "w"), indent=1)

    def line(name, s):
        mf = s["mid_confidence_follow"]
        print(f"{name:12s} mean {s['primary']:.3f} parts " + " ".join(f"{p}:{s['parts'][p]:.3f}" for p in S.PARTS)
              + f" | lowest floor {min(s['floors'].values()):.2f} | R-hear v1/v2/v3 "
              + "/".join(f"{s['r_hear_versions'][v]:.3f}" for v in ("1", "2", "3"))
              + f" | mid follow real {mf['real'][0]}/{mf['real'][1]} false {mf['false'][0]}/{mf['false'][1]}"
              + (f" | injected {s['injected_primary']:.3f}" if "injected_primary" in s else "")
              + " | noise " + " ".join(f"{n.split('/')[-1][:12]}:{v:.3f}" for n, v in s["noise"].items()))
    line("ours", res["reference"]["ours"])
    line("B2-strong", res["reference"]["B2-strong"])
    for name, s in res["variants"].items():
        line(name, s)
        print(f"{'':12s} thresholds S {s['th_s']} R {s['th_r']}, floors met {s['floors_met']}, mismatched questions "
              f"{s['mismatch']}")
    p = res["variants"][PRIMARY]
    for k, v in p["vs_B2_strong"].items():
        print(f"combination - B2-strong {k}: {v['point']:+.3f} [{v['ci95'][0]:+.3f}, {v['ci95'][1]:+.3f}]")
    for k, v in p["vs_ours"].items():
        print(f"combination - ours {k}: {v['point']:+.3f} [{v['ci95'][0]:+.3f}, {v['ci95'][1]:+.3f}]")
    for n, v in p["vs_B2_strong_without_noise"].items():
        print(f"combination - B2-strong without {n.split('/')[-1]}: {v['point']:+.3f} "
              f"[{v['ci95'][0]:+.3f}, {v['ci95'][1]:+.3f}]")


if __name__ == "__main__":
    main()
